import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const projectRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const sourceRoot = path.join(projectRoot, "src");
const outputPath = path.join(sourceRoot, "Nebula.lua");
const entryName = "NebulaCore";

function collectLuaFiles(directory) {
  return fs.readdirSync(directory, { withFileTypes: true }).flatMap((entry) => {
    const absolutePath = path.join(directory, entry.name);
    if (entry.isDirectory()) return collectLuaFiles(absolutePath);
    return entry.isFile() && entry.name.endsWith(".lua") ? [absolutePath] : [];
  });
}

function toModuleId(relativePath) {
  return relativePath
    .replaceAll(path.sep, "/")
    .replace(/\.lua$/, "")
    .split("/")
    .join(".");
}

const files = collectLuaFiles(sourceRoot)
  .filter((file) => path.resolve(file) !== path.resolve(outputPath))
  .sort((a, b) => a.localeCompare(b));

const moduleIds = new Set(
  files.map((file) => toModuleId(path.relative(sourceRoot, file))),
);
if (!moduleIds.has(entryName)) {
  throw new Error(`Missing src/${entryName}.lua bundle entry source`);
}

function rewriteRequires(source, relativePath) {
  const moduleId = toModuleId(relativePath);
  const isPackageEntry = moduleId === entryName;
  const initialPath = isPackageEntry ? [] : moduleId.split(".");

  const rewritten = source.replace(
    /require\(\s*(script(?:\.[A-Za-z_][A-Za-z0-9_]*)+)\s*\)/g,
    (_match, expression) => {
      const resolved = [...initialPath];
      const segments = expression.slice("script".length).split(".").filter(Boolean);

      for (const segment of segments) {
        if (segment === "Parent") {
          if (resolved.length === 0) {
            throw new Error(`require() walks above the package root in ${relativePath}`);
          }
          resolved.pop();
        } else {
          resolved.push(segment);
        }
      }

      const dependencyId = resolved.join(".");
      if (!moduleIds.has(dependencyId)) {
        throw new Error(`${relativePath} references missing module ${dependencyId}`);
      }
      return `require(${JSON.stringify(dependencyId)})`;
    },
  )
    .replace(/^\s*export\s+type\s+/gm, "type ");

  if (/\brequire\s*\(\s*script(?:\.|\s|\))/i.test(rewritten)) {
    throw new Error(`Unbundled require() found in ${relativePath}`);
  }
  return rewritten.replace(/^\s*--!strict\s*\n/, "");
}

const chunks = [
  "--!strict",
  "-- Generated by tools/build-bundle.mjs from the Nebula LIB source modules.",
  "-- Keep this file committed: it is the self-contained ModuleScript/loadstring entry point.",
  "local __factories = {}",
];

for (const file of files) {
  const relativePath = path.relative(sourceRoot, file);
  const id = toModuleId(relativePath);
  const source = fs.readFileSync(file, "utf8");
  chunks.push(
    `__factories[${JSON.stringify(id)}] = function(require)`,
    rewriteRequires(source, relativePath).trimEnd(),
    "end",
  );
}

chunks.push(
  "local __cache = {}",
  "local function __require(name)",
  "    local cached = __cache[name]",
  "    if cached ~= nil then",
  "        return cached",
  "    end",
  "    local factory = __factories[name]",
  '    assert(factory, ("Nebula bundle: module not found: %s"):format(tostring(name)))',
  "    local value = factory(__require)",
  "    __cache[name] = value",
  "    return value",
  "end",
  `return __require(${JSON.stringify(entryName)})`,
);

fs.writeFileSync(outputPath, `${chunks.join("\n\n")}\n`);
console.info(`Built src/Nebula.lua with ${files.length} bundled modules.`);